import json, subprocess, warnings, os
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "रात में पैरों में ऐंठन? हाथ पैर में झनझनाहट? किडनी में पथरी? आज मंगलवार की हेल्थ टिप में जानिए, कैल्शियम और फॉस्फोरस टेस्ट. आखिर तक देखिए.",
 "शरीर का लगभग सारा कैल्शियम, और लगभग पचासी प्रतिशत फॉस्फोरस, हड्डियों और दांतों में होता है. खून का थोड़ा सा कैल्शियम, मांसपेशियों और नसों के लिए ज़रूरी है. पैराथायरॉइड, विटामिन डी और किडनी इसे कंट्रोल करते हैं. कैल्शियम बढ़े, तो फॉस्फोरस अक्सर घटता है, इसलिए दोनों साथ जांचे जाते हैं.",
 "कैल्शियम कम हो, तो उंगलियों या होंठों के आसपास झनझनाहट, ऐंठन, और फड़कन हो सकती है. कैल्शियम ज़्यादा हो, तो शुरू में अक्सर कोई लक्षण नहीं. बाद में प्यास, बार बार पेशाब, थकान, कब्ज़, मतली, और पथरी हो सकती है.",
 "कैल्शियम ज़्यादा, सबसे अक्सर पैराथायरॉइड के ज़्यादा काम करने से, या कुछ कैंसर में. कैल्शियम कम, विटामिन डी की कमी, पैराथायरॉइड कम काम करे, किडनी की बीमारी, या एल्ब्यूमिन और मैग्नीशियम की कमी से. फॉस्फोरस ज़्यादा, अक्सर किडनी की समस्या में.",
 "किसे ज़रूरत हो सकती है? रूटीन चेकअप. ऊपर बताए लक्षण. किडनी, पैराथायरॉइड या हड्डी की समस्या. बार बार पथरी हो, तो पेशाब में कैल्शियम की जांच. और कैल्शियम पर असर डालने वाली दवाओं की निगरानी में.",
 "तैयारी. सिर्फ कैल्शियम टेस्ट में आमतौर पर खास तैयारी नहीं, दूसरे टेस्ट के साथ कुछ घंटे खाली पेट कहा जा सकता है. कैल्शियम, विटामिन डी, एंटासिड, पेशाब की गोली, या थायरॉइड की दवा लेते हैं, तो डॉक्टर को बताएं. अपने आप दवा बंद न करें.",
 "रिपोर्ट. बड़ों में टोटल कैल्शियम, लगभग साढ़े आठ से सवा दस, एम जी पर डी एल. फॉस्फोरस लगभग पौने तीन से साढ़े चार. बच्चों में फॉस्फोरस ज़्यादा होता है, क्योंकि हड्डियां बढ़ रही हैं. रेंज हर लैब में अलग होती है, अपनी रिपोर्ट की रेंज देखें.",
 "खून का लगभग आधा कैल्शियम एल्ब्यूमिन से जुड़ा होता है. एल्ब्यूमिन कम हो, तो डॉक्टर आयोनाइज़्ड कैल्शियम करवा सकते हैं. मिथक, खून में कैल्शियम नॉर्मल, यानी हड्डियां मज़बूत. सच, शरीर हड्डियों से कैल्शियम लेकर खून का लेवल बनाए रखता है. हड्डियों के लिए बोन डेंसिटी स्कैन होता है. और कैल्शियम स्कोर, दिल की नसों का सी टी स्कैन है.",
 close_voice("क्या आपने कभी कैल्शियम टेस्ट करवाया है?"),
]
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/calr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/cal_{i}.wav"],check=True); f=f"/tmp/cal_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/cal_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
